+bool RequiresIterableSpreadMaterialization(checker::Type *spreadType)
+{
+    return spreadType != nullptr && !spreadType->IsETSTupleType() && !util::Helpers::IsArrayType(spreadType);
+}
+
+static void CollectSpreadConstituentTypes(checker::Type *type, std::vector<checker::Type *> &types)
+{
+    if (type->IsETSUnionType()) {
+        for (auto *const constituentType : type->AsETSUnionType()->ConstituentTypes()) {
+            CollectSpreadConstituentTypes(constituentType, types);
+        }
+        return;
+    }
+
+    types.emplace_back(type);
+}
+
+template <class Predicate>
+static bool HasSpreadConstituentType(checker::Type *spreadType, Predicate predicate)
+{
+    std::vector<checker::Type *> constituentTypes;
+    CollectSpreadConstituentTypes(spreadType, constituentTypes);
+    return std::any_of(constituentTypes.cbegin(), constituentTypes.cend(), predicate);
+}
+
+static bool NeedsArrayInstanceofBranch(checker::Type *spreadType)
+{
+    return HasSpreadConstituentType(spreadType, [](checker::Type *const constituentType) {
+        return constituentType->IsETSResizableArrayType() || constituentType->IsETSReadonlyArrayType();
+    });
+}
+
+static bool NeedsFixedArrayInstanceofBranch(checker::Type *spreadType)
+{
+    return HasSpreadConstituentType(
+        spreadType, [](checker::Type *const constituentType) { return constituentType->IsETSArrayType(); });
+}
+
+static bool NeedsTupleInstanceofBranch(checker::Type *spreadType)
+{
+    return HasSpreadConstituentType(
+        spreadType, [](checker::Type *const constituentType) { return constituentType->IsETSTupleType(); });
+}
+
+static bool NeedsIterableFallbackBranch(checker::Type *spreadType)
+{
+    return HasSpreadConstituentType(spreadType, [](checker::Type *const constituentType) {
+        return !constituentType->IsETSTupleType() && !util::Helpers::IsArrayType(constituentType);
+    });
+}
+
+static auto AddIdent(std::vector<ir::AstNode *> &nodesWaitingInsert, ArenaAllocator *allocator, ir::Identifier *ident)
+    -> std::string
+{
+    nodesWaitingInsert.emplace_back(ident->Clone(allocator, nullptr));
+    return "@@I" + std::to_string(nodesWaitingInsert.size());
+}
+
+static auto AddExpr(std::vector<ir::AstNode *> &nodesWaitingInsert, ArenaAllocator *allocator, ir::Expression *expr)
+    -> std::string
+{
+    nodesWaitingInsert.emplace_back(expr->Clone(allocator, nullptr));
+    return "@@E" + std::to_string(nodesWaitingInsert.size());
+}
+
+static auto AddType(std::vector<ir::AstNode *> &nodesWaitingInsert, checker::ETSChecker *checker,
+                    ArenaAllocator *allocator, checker::Type *type) -> std::string
+{
+    nodesWaitingInsert.emplace_back(checker->AllocNode<ir::OpaqueTypeNode>(type, allocator));
+    return "@@T" + std::to_string(nodesWaitingInsert.size());
+}
+
+static void AppendIterableSpreadMaterializationPreamble(std::stringstream &ss,
+                                                        std::vector<ir::AstNode *> &nodesWaitingInsert,
+                                                        checker::ETSChecker *checker, ArenaAllocator *allocator,
+                                                        checker::Type *elementType, ir::Identifier *targetArrayIdent,
+                                                        ir::Identifier *spreadArgIdent, ir::Expression *argument)
+{
+    ss << "let " << AddIdent(nodesWaitingInsert, allocator, targetArrayIdent) << ": Array<"
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << "> = new Array<"
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << ">();";
+    ss << "let " << AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) << " = "
+       << AddExpr(nodesWaitingInsert, allocator, argument) << ";";
+}
+
+static void AppendIterableSpreadArrayCopy(std::stringstream &ss, std::vector<ir::AstNode *> &nodesWaitingInsert,
+                                          checker::ETSChecker *checker, ArenaAllocator *allocator,
+                                          checker::Type *elementType, ir::Identifier *targetArrayIdent,
+                                          ir::Identifier *spreadArgIdent, const std::string &condition,
+                                          const std::string &castType, bool isElseIf)
+{
+    auto *const sourceIdent = Gensym(allocator);
+    auto *const sourceIndexIdent = Gensym(allocator);
+    ss << (isElseIf ? " else if (" : "if (") << condition << ") {";
+    ss << "let " << AddIdent(nodesWaitingInsert, allocator, sourceIdent) << ": Array<"
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << "> = Array.from<"
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << ">("
+       << AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) << " as " << castType << ");";
+    ss << "for (let " << AddIdent(nodesWaitingInsert, allocator, sourceIndexIdent) << " = 0; "
+       << AddIdent(nodesWaitingInsert, allocator, sourceIndexIdent) << " < "
+       << AddIdent(nodesWaitingInsert, allocator, sourceIdent) << ".length; "
+       << AddIdent(nodesWaitingInsert, allocator, sourceIndexIdent) << "++) {";
+    ss << AddIdent(nodesWaitingInsert, allocator, targetArrayIdent) << ".push("
+       << AddIdent(nodesWaitingInsert, allocator, sourceIdent) << "["
+       << AddIdent(nodesWaitingInsert, allocator, sourceIndexIdent) << "] as "
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << ");";
+    ss << "}";
+    ss << "}";
+}
+
+static void AppendIterableSpreadArrayBranch(std::stringstream &ss, std::vector<ir::AstNode *> &nodesWaitingInsert,
+                                            checker::ETSChecker *checker, ArenaAllocator *allocator,
+                                            checker::Type *spreadType, checker::Type *elementType,
+                                            ir::Identifier *targetArrayIdent, ir::Identifier *spreadArgIdent,
+                                            bool &hasConditionalBranch)
+{
+    if (!NeedsArrayInstanceofBranch(spreadType)) {
+        return;
+    }
+
+    auto *const runtimeArrayIdent = Gensym(allocator);
+    auto *const arrayIndexIdent = Gensym(allocator);
+    ss << "if (" << AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) << " instanceof Array) {";
+    ss << "let " << AddIdent(nodesWaitingInsert, allocator, runtimeArrayIdent)
+       << ": Array<Any> = " << AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) << " as Array<Any>;";
+    ss << "for (let " << AddIdent(nodesWaitingInsert, allocator, arrayIndexIdent) << " = 0; "
+       << AddIdent(nodesWaitingInsert, allocator, arrayIndexIdent) << " < "
+       << AddIdent(nodesWaitingInsert, allocator, runtimeArrayIdent) << ".length; "
+       << AddIdent(nodesWaitingInsert, allocator, arrayIndexIdent) << "++) {";
+    ss << AddIdent(nodesWaitingInsert, allocator, targetArrayIdent) << ".push("
+       << AddIdent(nodesWaitingInsert, allocator, runtimeArrayIdent) << "["
+       << AddIdent(nodesWaitingInsert, allocator, arrayIndexIdent) << "] as "
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << ");";
+    ss << "}";
+    ss << "}";
+    hasConditionalBranch = true;
+}
+
+static void AppendIterableSpreadFixedArrayBranches(std::stringstream &ss,
+                                                   std::vector<ir::AstNode *> &nodesWaitingInsert,
+                                                   checker::ETSChecker *checker, ArenaAllocator *allocator,
+                                                   checker::Type *spreadType, checker::Type *elementType,
+                                                   ir::Identifier *targetArrayIdent, ir::Identifier *spreadArgIdent,
+                                                   bool &hasConditionalBranch)
+{
+    if (!NeedsFixedArrayInstanceofBranch(spreadType)) {
+        return;
+    }
+
+    std::vector<checker::Type *> constituentTypes;
+    CollectSpreadConstituentTypes(spreadType, constituentTypes);
+    for (auto *const constituentType : constituentTypes) {
+        if (!constituentType->IsETSArrayType()) {
+            continue;
+        }
+
+        auto const condition = AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) + " instanceof " +
+                               AddType(nodesWaitingInsert, checker, allocator, constituentType);
+        auto const castType = AddType(nodesWaitingInsert, checker, allocator, constituentType);
+        AppendIterableSpreadArrayCopy(ss, nodesWaitingInsert, checker, allocator, elementType, targetArrayIdent,
+                                      spreadArgIdent, condition, castType, hasConditionalBranch);
+        hasConditionalBranch = true;
+    }
+}
+
+static void AppendIterableSpreadTupleBranches(std::stringstream &ss, std::vector<ir::AstNode *> &nodesWaitingInsert,
+                                              checker::ETSChecker *checker, ArenaAllocator *allocator,
+                                              checker::Type *spreadType, checker::Type *elementType,
+                                              ir::Identifier *targetArrayIdent, ir::Identifier *spreadArgIdent,
+                                              bool &hasConditionalBranch)
+{
+    if (!NeedsTupleInstanceofBranch(spreadType)) {
+        return;
+    }
+
+    std::vector<checker::Type *> constituentTypes;
+    CollectSpreadConstituentTypes(spreadType, constituentTypes);
+    for (auto *const constituentType : constituentTypes) {
+        if (!constituentType->IsETSTupleType()) {
+            continue;
+        }
+
+        auto *const sourceIdent = Gensym(allocator);
+        auto const condition = AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) + " instanceof " +
+                               AddType(nodesWaitingInsert, checker, allocator, constituentType);
+        auto const sourceType = AddType(nodesWaitingInsert, checker, allocator, constituentType);
+        ss << (hasConditionalBranch ? " else if (" : "if (") << condition << ") {";
+        ss << "let " << AddIdent(nodesWaitingInsert, allocator, sourceIdent) << ": " << sourceType << " = "
+           << AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) << " as "
+           << AddType(nodesWaitingInsert, checker, allocator, constituentType) << ";";
+        for (size_t index = 0; index < constituentType->AsETSTupleType()->GetTupleSize(); ++index) {
+            ss << AddIdent(nodesWaitingInsert, allocator, targetArrayIdent) << ".push("
+               << AddIdent(nodesWaitingInsert, allocator, sourceIdent) << "[" << index << "] as "
+               << AddType(nodesWaitingInsert, checker, allocator, elementType) << ");";
+        }
+        ss << "}";
+        hasConditionalBranch = true;
+    }
+}
+
+static void AppendIterableSpreadFallback(std::stringstream &ss, std::vector<ir::AstNode *> &nodesWaitingInsert,
+                                         checker::ETSChecker *checker, ArenaAllocator *allocator,
+                                         checker::Type *spreadType, checker::Type *elementType,
+                                         ir::Identifier *targetArrayIdent, ir::Identifier *spreadArgIdent,
+                                         bool hasConditionalBranch)
+{
+    auto *const iterValueIdent = Gensym(allocator);
+    if (!NeedsIterableFallbackBranch(spreadType)) {
+        return;
+    }
+
+    if (hasConditionalBranch) {
+        ss << " else {";
+    }
+    ss << "for (let " << AddIdent(nodesWaitingInsert, allocator, iterValueIdent) << ": "
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << " of ("
+       << AddIdent(nodesWaitingInsert, allocator, spreadArgIdent) << " as Iterable<"
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << ">)) {";
+    ss << AddIdent(nodesWaitingInsert, allocator, targetArrayIdent) << ".push("
+       << AddIdent(nodesWaitingInsert, allocator, iterValueIdent) << " as "
+       << AddType(nodesWaitingInsert, checker, allocator, elementType) << ");";
+    ss << "}";
+    if (hasConditionalBranch) {
+        ss << "}";
+    }
+}
+
+void CreateIterableSpreadMaterialization(public_lib::Context *ctx, ir::Expression *spreadArgument,
+                                         ir::Identifier *targetArrayIdent, ArenaVector<ir::Statement *> &statements)
+{
+    auto *const checker = ctx->GetChecker()->AsETSChecker();
+    auto *const allocator = ctx->allocator;
+    auto *const parser = ctx->parser->AsETSParser();
+    auto *const spreadType = spreadArgument->TsType();
+    auto *const elementType = checker::GetElementTypeOfSpreadType(checker, spreadType);
+    auto *const spreadArgIdent = Gensym(allocator);
+    std::vector<ir::AstNode *> nodesWaitingInsert;
+    std::stringstream ss;
+    bool hasConditionalBranch = false;
+    ES2PANDA_ASSERT(elementType != nullptr);
+    ES2PANDA_ASSERT(!elementType->IsTypeError());
+
+    spreadArgIdent->SetTsType(spreadType);
+    targetArrayIdent->SetTsType(checker->CreateETSResizableArrayType(checker->GetNonConstantType(elementType)));
+    AppendIterableSpreadMaterializationPreamble(ss, nodesWaitingInsert, checker, allocator, elementType,
+                                                targetArrayIdent, spreadArgIdent, spreadArgument);
+    AppendIterableSpreadArrayBranch(ss, nodesWaitingInsert, checker, allocator, spreadType, elementType,
+                                    targetArrayIdent, spreadArgIdent, hasConditionalBranch);
+    AppendIterableSpreadFixedArrayBranches(ss, nodesWaitingInsert, checker, allocator, spreadType, elementType,
+                                           targetArrayIdent, spreadArgIdent, hasConditionalBranch);
+    AppendIterableSpreadTupleBranches(ss, nodesWaitingInsert, checker, allocator, spreadType, elementType,
+                                      targetArrayIdent, spreadArgIdent, hasConditionalBranch);
+    AppendIterableSpreadFallback(ss, nodesWaitingInsert, checker, allocator, spreadType, elementType, targetArrayIdent,
+                                 spreadArgIdent, hasConditionalBranch);
+
+    auto generatedStatements = parser->CreateFormattedStatements(ss.str(), nodesWaitingInsert);
+    statements.insert(statements.cend(), generatedStatements.cbegin(), generatedStatements.cend());
+}
+
+}  // namespace ark::es2panda::compiler
