+static Type *NormalizeSpreadType(ETSChecker *checker, Type *type)
+{
+    while (type != nullptr && type->IsETSTypeAliasType()) {
+        type = checker->GetNonConstantType(type->AsETSTypeAliasType()->GetTargetType());
+    }
+
+    return type == nullptr ? checker->GlobalTypeError() : checker->GetNonConstantType(type);
