+static bool HasIteratorInterface(ETSObjectType *type)
+{
+    if (type == nullptr) {
+        return false;
+    }
+
+    if (type->Name().Is(ir::ITERATOR_INTERFACE_NAME)) {
+        return true;
+    }
+
+    if (std::any_of(type->Interfaces().begin(), type->Interfaces().end(), [](auto *interfaceType) {
+            return interfaceType != nullptr && interfaceType->Name().Is(ir::ITERATOR_INTERFACE_NAME);
+        })) {
+        return true;
+    }
+
+    return type->SuperType() != nullptr && type->SuperType()->IsETSObjectType() &&
+           HasIteratorInterface(type->SuperType()->AsETSObjectType());
+}
+
+static PropertySearchFlags BuildSpreadTypeSearchFlags(ETSObjectType *type)
+{
+    auto searchFlags = PropertySearchFlags::SEARCH_INSTANCE_METHOD | PropertySearchFlags::SEARCH_IN_INTERFACES;
+    if (type->HasTypeFlag(TypeFlag::GENERIC)) {
+        searchFlags |= PropertySearchFlags::SEARCH_ALL;
+    }
+    if (type->HasObjectFlag(ETSObjectFlags::CLASS)) {
+        searchFlags |= PropertySearchFlags::SEARCH_IN_BASE;
+    }
+
+    return searchFlags;
+}
+
+static Signature *FindZeroArgSignature(ETSFunctionType *functionType)
+{
+    if (functionType == nullptr) {
+        return nullptr;
+    }
+
+    for (auto *const signature : functionType->CallSignatures()) {
+        if (signature->Params().empty()) {
+            return signature;
+        }
+    }
+
+    return nullptr;
+}
+
+// Keep spread element extraction side-effect-free; diagnostics are emitted by callers.
+static Type *ResolveIterableElementType(ETSChecker *checker, Type *type)
+{
+    type = NormalizeSpreadType(checker, type);
+    if (!type->IsETSObjectType()) {
+        return checker->GlobalTypeError();
+    }
+
+    auto *const sourceType = type->AsETSObjectType();
+    auto const searchFlags = BuildSpreadTypeSearchFlags(sourceType);
+    auto *const method = sourceType->GetProperty(compiler::Signatures::ITERATOR_METHOD, searchFlags);
+    if (method == nullptr || !method->HasFlag(varbinder::VariableFlags::METHOD) || method->TsType() == nullptr ||
+        !method->TsType()->IsETSFunctionType()) {
+        return checker->GlobalTypeError();
+    }
+
+    auto *const iteratorSignature = FindZeroArgSignature(method->TsType()->AsETSFunctionType());
+    if (iteratorSignature == nullptr || iteratorSignature->ReturnType() == nullptr) {
+        return checker->GlobalTypeError();
+    }
+
+    auto *iteratorType = NormalizeSpreadType(checker, iteratorSignature->ReturnType());
+    if (!iteratorType->IsETSObjectType() || !HasIteratorInterface(iteratorType->AsETSObjectType())) {
+        return checker->GlobalTypeError();
+    }
+
+    auto *const iteratorObjectType = iteratorType->AsETSObjectType();
+    auto const iteratorSearchFlags = BuildSpreadTypeSearchFlags(iteratorObjectType);
+    auto *const nextMethod = iteratorObjectType->GetProperty(ir::ITERATOR_INTERFACE_METHOD, iteratorSearchFlags);
+    if (nextMethod == nullptr || !nextMethod->HasFlag(varbinder::VariableFlags::METHOD) ||
+        nextMethod->TsType() == nullptr || !nextMethod->TsType()->IsETSFunctionType()) {
+        return checker->GlobalTypeError();
+    }
+
+    auto *const nextSignature = FindZeroArgSignature(nextMethod->TsType()->AsETSFunctionType());
+    if (nextSignature == nullptr || nextSignature->ReturnType() == nullptr) {
+        return checker->GlobalTypeError();
+    }
+
+    auto *nextReturnType = NormalizeSpreadType(checker, nextSignature->ReturnType());
+    if (!nextReturnType->IsETSObjectType() || !nextReturnType->AsETSObjectType()->Name().Is(ir::ITERATOR_RESULT_NAME)) {
+        return checker->GlobalTypeError();
+    }
+
+    auto const &typeArguments = nextReturnType->AsETSObjectType()->TypeArguments();
+    return typeArguments.empty() ? checker->GlobalTypeError() : typeArguments.front();
+}
+
+class SpreadElementTypeCollector final {
+public:
+    static bool Collect(ETSChecker *checker, Type *type, std::vector<Type *> &elementTypes)
+    {
+        type = NormalizeSpreadType(checker, type);
+        if (type->IsTypeError()) {
+            return false;
+        }
+
+        if (type->IsETSUnionType()) {
+            for (auto *const constituentType : type->AsETSUnionType()->ConstituentTypes()) {
+                if (!Collect(checker, constituentType, elementTypes)) {
+                    return false;
+                }
+            }
+            return !elementTypes.empty();
+        }
+
+        if (type->IsETSStringType()) {
+            elementTypes.emplace_back(checker->GlobalBuiltinETSStringType());
+            return true;
+        }
+
+        if (type->IsETSTupleType()) {
+            elementTypes.emplace_back(
+                util::Helpers::CreateUnionOfTupleConstituentTypes(checker, type->AsETSTupleType()));
+            return true;
+        }
+
+        if (util::Helpers::IsArrayType(type)) {
+            elementTypes.emplace_back(checker->GetElementTypeOfArray(type));
+            return true;
+        }
+
+        auto *const iterableElementType = ResolveIterableElementType(checker, type);
+        if (!iterableElementType->IsTypeError()) {
+            elementTypes.emplace_back(iterableElementType);
+            return true;
+        }
+
+        return false;
+    }
+};
+
+bool IsValidSpreadType(ETSChecker *checker, Type *type)
+{
+    std::vector<Type *> elementTypes;
+    return SpreadElementTypeCollector::Collect(checker, type, elementTypes);
+}
+
+Type *GetElementTypeOfSpreadType(ETSChecker *checker, Type *type)
+{
+    std::vector<Type *> elementTypes;
+    if (!SpreadElementTypeCollector::Collect(checker, type, elementTypes) || elementTypes.empty()) {
+        return checker->GlobalTypeError();
+    }
+
+    if (elementTypes.size() == 1U) {
+        return elementTypes.front();
+    }
+
+    auto *const unionType = checker->CreateETSUnionType(std::move(elementTypes));
+    return checker->GetNonConstantType(unionType->IsETSUnionType() ? unionType->AsETSUnionType()->NormalizedType()
+                                                                   : unionType);
+}
