bool RequiresIterableSpreadMaterialization(checker::Type *spreadType)
{
    return spreadType != nullptr && !spreadType->IsETSTupleType() && !util::Helpers::IsArrayType(spreadType);
}

class IterableSpreadMaterializationBuilder final {
public:
    IterableSpreadMaterializationBuilder(public_lib::Context *ctx, ir::Expression *spreadArgument,
                                         ir::Identifier *targetArrayIdent)
        : checker_(ctx->GetChecker()->AsETSChecker()),
          allocator_(ctx->allocator),
          parser_(ctx->parser->AsETSParser()),
          spreadArgument_(spreadArgument),
          targetArrayIdent_(targetArrayIdent),
          spreadType_(spreadArgument->TsType()),
          elementType_(checker::GetElementTypeOfSpreadType(checker_, spreadType_)),
          spreadArgIdent_(Gensym(allocator_)),
          iterValueIdent_(Gensym(allocator_))
    {
    }

    IterableSpreadMaterializationBuilder(public_lib::Context *ctx, ir::Expression *spreadArgument,
                                         ir::Identifier *targetArrayIdent, const IterableSpreadStorage &storage)
        : IterableSpreadMaterializationBuilder(ctx, spreadArgument, targetArrayIdent)
    {
        storage_ = &storage;
    }

    void AppendTo(ArenaVector<ir::Statement *> &statements)
    {
        ES2PANDA_ASSERT(elementType_ != nullptr);
        ES2PANDA_ASSERT(!elementType_->IsTypeError());

        spreadArgIdent_->SetTsType(spreadType_);
        targetArrayIdent_->SetTsType(checker_->CreateETSResizableArrayType(checker_->GetNonConstantType(elementType_)));

        AppendPreamble();
        AppendTupleBranches();
        AppendArrayBranches();
        AppendForOfFallback();
        AppendStoreMaterializedArgument();

        auto generatedStatements = parser_->CreateFormattedStatements(ss_.str(), nodesWaitingInsert_);
        statements.insert(statements.cend(), generatedStatements.cbegin(), generatedStatements.cend());
    }

private:
    static void CollectConstituentTypes(checker::Type *type, std::vector<checker::Type *> &types)
    {
        if (type->IsETSUnionType()) {
            for (auto *const constituentType : type->AsETSUnionType()->ConstituentTypes()) {
                CollectConstituentTypes(constituentType, types);
            }
            return;
        }

        types.emplace_back(type);
    }

    auto AddIdentName(const std::string &name) -> std::string
    {
        nodesWaitingInsert_.emplace_back(
            allocator_->New<ir::Identifier>(util::UString(name, allocator_).View(), allocator_));
        return "@@I" + std::to_string(nodesWaitingInsert_.size());
    }

    auto AddIdent(ir::Identifier *ident) -> std::string
    {
        return AddIdentName(std::string(ident->Name().Utf8()));
    }

    auto AddExpr(ir::Expression *expr) -> std::string
    {
        nodesWaitingInsert_.emplace_back(expr);
        return "@@E" + std::to_string(nodesWaitingInsert_.size());
    }

    auto AddType(checker::Type *type) -> std::string
    {
        nodesWaitingInsert_.emplace_back(checker_->AllocNode<ir::OpaqueTypeNode>(type, allocator_));
        return "@@T" + std::to_string(nodesWaitingInsert_.size());
    }

    void AppendPreamble()
    {
        ss_ << "let " << AddIdent(targetArrayIdent_) << ": Array<" << AddType(elementType_) << "> = new Array<"
            << AddType(elementType_) << ">();";
        ss_ << "let " << AddIdent(spreadArgIdent_) << " = " << AddExpr(spreadArgument_) << ";";
    }

    void AppendTupleBranches()
    {
        std::vector<checker::Type *> constituentTypes;
        CollectConstituentTypes(spreadType_, constituentTypes);
        for (auto *const constituentType : constituentTypes) {
            if (!constituentType->IsETSTupleType()) {
                continue;
            }

            auto *const sourceIdent = Gensym(allocator_);
            auto const condition = AddIdent(spreadArgIdent_) + " instanceof " + AddType(constituentType);
            auto const sourceType = AddType(constituentType);
            ss_ << (hasConditionalBranch_ ? " else if (" : "if (") << condition << ") {";
            ss_ << "let " << AddIdent(sourceIdent) << ": " << sourceType << " = " << AddIdent(spreadArgIdent_) << " as "
                << AddType(constituentType) << ";";
            for (size_t index = 0; index < constituentType->AsETSTupleType()->GetTupleSize(); ++index) {
                ss_ << AddIdent(targetArrayIdent_) << ".push(" << AddIdent(sourceIdent) << "[" << index << "] as "
                    << AddType(elementType_) << ");";
            }
            ss_ << "}";
            hasConditionalBranch_ = true;
        }
    }

    void AppendArrayBranches()
    {
        std::vector<checker::Type *> constituentTypes;
        CollectConstituentTypes(spreadType_, constituentTypes);
        for (auto *const constituentType : constituentTypes) {
            if (!util::Helpers::IsArrayType(constituentType)) {
                continue;
            }
            AppendArrayBranch(constituentType);
        }
    }

    void AppendArrayBranch(checker::Type *arrayType)
    {
        auto *const valueIdent = Gensym(allocator_);
        valueIdent->SetTsType(checker_->GetElementTypeOfArray(arrayType));
        ss_ << (hasConditionalBranch_ ? " else if (" : "if (") << AddIdent(spreadArgIdent_) << " instanceof "
            << AddType(arrayType) << ") {";
        ss_ << "for (let " << AddIdent(valueIdent) << ": " << AddType(valueIdent->TsType()) << " of ("
            << AddIdent(spreadArgIdent_) << " as " << AddType(arrayType) << ")) {";
        ss_ << AddIdent(targetArrayIdent_) << ".push(" << AddIdent(valueIdent) << " as " << AddType(elementType_)
            << ");";
        ss_ << "}}";
        hasConditionalBranch_ = true;
    }

    void AppendForOfFallback()
    {
        if (hasConditionalBranch_) {
            ss_ << " else {";
        }
        ss_ << "for (let " << AddIdent(iterValueIdent_) << ": " << AddType(elementType_) << " of ";
        if (hasConditionalBranch_) {
            ss_ << "(" << AddIdent(spreadArgIdent_) << " as Iterable<" << AddType(elementType_) << ">)";
        } else {
            ss_ << AddIdent(spreadArgIdent_);
        }
        ss_ << ") {";
        ss_ << AddIdent(targetArrayIdent_) << ".push(" << AddIdent(iterValueIdent_) << " as " << AddType(elementType_)
            << ");";
        ss_ << "}";
        if (hasConditionalBranch_) {
            ss_ << "}";
        }
    }

    void AppendStoreMaterializedArgument()
    {
        if (storage_ == nullptr) {
            return;
        }
        ss_ << AddIdentName(storage_->spreadArgsArray) << "[" << storage_->spreadArgIndex
            << "] = " << AddIdent(targetArrayIdent_) << ";";
    }

    checker::ETSChecker *checker_;
    ArenaAllocator *allocator_;
    parser::ETSParser *parser_;
    ir::Expression *spreadArgument_;
    ir::Identifier *targetArrayIdent_;
    checker::Type *spreadType_;
    checker::Type *elementType_;
    ir::Identifier *spreadArgIdent_;
    ir::Identifier *iterValueIdent_;
    std::vector<ir::AstNode *> nodesWaitingInsert_;
    std::stringstream ss_;
    const IterableSpreadStorage *storage_ {nullptr};
    bool hasConditionalBranch_ {false};
};

void CreateIterableSpreadMaterialization(public_lib::Context *ctx, ir::Expression *spreadArgument,
                                         ir::Identifier *targetArrayIdent, ArenaVector<ir::Statement *> &statements)
{
    IterableSpreadMaterializationBuilder(ctx, spreadArgument, targetArrayIdent).AppendTo(statements);
}

void CreateIterableSpreadMaterializationAndStore(public_lib::Context *ctx, ir::Expression *spreadArgument,
                                                 const IterableSpreadStorage &storage,
                                                 ArenaVector<ir::Statement *> &statements)
{
    auto *const targetArrayIdent = Gensym(ctx->allocator);
    IterableSpreadMaterializationBuilder(ctx, spreadArgument, targetArrayIdent, storage).AppendTo(statements);
}

